/**
 * @method
 * @name bullish#fetchTime
 * @description fetches the current integer timestamp in milliseconds from the exchange server
 * @see https://api.exchange.bullish.com/docs/api/rest/trading-api/v2/#tag--time
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {int} the current integer timestamp in milliseconds from the exchange server
 */
func (this *Bullish) FetchTimeAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchTimeBody(ch, optionalArgs...)
	return ch
}
func (this *Bullish) fetchTimeBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	var response map[string]any = MapTyped(PanicOnError((<-this.PublicGetV1Time(params)).Raw))

	//
	//     {
	//         "datetime": "2025-05-05T20:05:50.999Z",
	//         "timestamp": 1746475550999
	//     }
	//
	ch <- this.SafeInteger(response, "timestamp")
	return nil
}

