func (this *Bullish) cancelAllOrdersBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params

	PanicOnError((<-promiseAll([]any{this.LoadMarketsAsync(), this.HandleTokenAsync()})))

	var tradingAccountId *string = SafeStringPtr(PanicOnError((<-this.LoadAccountAsync(params))))
	var request map[string]any = map[string]any{
		"tradingAccountId": tradingAccountId,
	}
	var market map[string]any = nil
	if symbol != nil {
		market = this.Market(symbol)
		request["symbol"] = GetValue(market, "id")
		request["commandType"] = "V1CancelAllOrdersByMarket"
	} else {
		request["commandType"] = "V1CancelAllOrders"
	}

	response := (<-this.PrivatePostV2Command(this.Extend(request, params))).Raw
	PanicOnError(response)
	//
	//     {
	//         "message": "Command acknowledged - CancelAllOrders",
	//         "requestId": "633900538459062272"
	//     }
	//
	var orders []any = []any{response}

	ch <- this.ParseOrders(orders, market)
	return nil
}
func (this *Bullish) ParseOrder(order any, optionalArgs ...any) any {
	//
	// fetchOrders, fetchOrder
	//     {
	//         "clientOrderId": "187",
	//         "orderId": "297735387747975680",
	//         "symbol": "BTCUSDC",
	//         "price": "1.00000000",
	//         "averageFillPrice": "1.00000000",
	//         "stopPrice": "1.00000000",
	//         "allowBorrow": false,
	//         "quantity": "1.00000000",
	//         "quantityFilled": "1.00000000",
	//         "quoteAmount": "1.00000000",
	//         "baseFee": "0.00100000",
	//         "quoteFee": "0.0010",
	//         "borrowedBaseQuantity": "1.00000000",
	//         "borrowedQuoteQuantity": "1.00000000",
	//         "isLiquidation": false,
	//         "side": "BUY",
	//         "type": "LMT",
	//         "timeInForce": "GTC",
	//         "status": "OPEN",
	//         "statusReason": "User cancelled",
	//         "statusReasonCode": "1002",
	//         "createdAtDatetime": "2021-05-20T01:01:01.000Z",
	//         "createdAtTimestamp": "1621490985000",
	//     }
	//
	// createOrder
	//     {
	//         "message": "Command acknowledged - CreateOrder",
	//         "requestId": "633910976353665024",
	//         "orderId": "633910775316480001",
	//         "clientOrderId": "1234567"
	//     }
	//
	// cancelOrder
	//     {
	//         "message": "Command acknowledged - CancelOrder",
	//         "requestId": "633910976353665024",
	//         "orderId": "633910775316480001"
	//     }
	//
	// cancelAllOrders
	//     {
	//         "message": "Command acknowledged - CancelAllOrders",
	//         "requestId": "633900538459062272"
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(order, "symbol")
	var marketResolved any = func() any {
		if market == nil {
			return this.SafeMarket(marketId)
		}
		return market
	}()
	var symbol *string = this.SafeSymbol(marketId, marketResolved)
	var id *string = this.SafeString(order, "orderId")
	var timestamp *int64 = this.SafeInteger(order, "createdAtTimestamp")
	var typeVar *string = this.SafeString(order, "type")
	var side *string = this.SafeStringLower(order, "side")
	var price *string = this.SafeString(order, "price")
	var amount *string = this.SafeString(order, "quantity")
	var filled *string = this.SafeString(order, "quantityFilled")
	var status *string = this.ParseOrderStatus(this.SafeString(order, "status"))
	if status != nil && *status == "closed" {
		var statusReason *string = this.SafeString(order, "statusReason")
		if statusReason != nil && *statusReason == "User cancelled" {
			status = SafeStringPtr("canceled")
		}
	}
	var timeInForce *string = this.SafeString(order, "timeInForce")
	var stopPrice *string = this.SafeString(order, "stopPrice")
	var cost *string = this.SafeString(order, "quoteAmount")
	var fee map[string]any = map[string]any{}
	var quoteFee *float64 = this.SafeNumber(order, "quoteFee")
	if quoteFee != nil {
		fee["cost"] = quoteFee
		fee["currency"] = GetValue(marketResolved, "quote")
	}
	var average *string = this.SafeString(order, "averageFillPrice")
	return this.SafeOrder(map[string]any{
		"id":                 id,
		"clientOrderId":      this.SafeString(order, "clientOrderId"),
		"timestamp":          timestamp,
		"datetime":           this.Iso8601(timestamp),
		"lastTradeTimestamp": nil,
		"status":             status,
		"symbol":             symbol,
		"type":               this.ParseOrderType(typeVar),
		"timeInForce":        timeInForce,
		"postOnly":           (typeVar != nil && *typeVar == "POST_ONLY"),
		"side":               side,
		"price":              price,
		"triggerPrice":       stopPrice,
		"amount":             amount,
		"filled":             filled,
		"remaining":          nil,
		"cost":               cost,
		"trades":             nil,
		"fee":                fee,
		"info":               order,
		"average":            average,
	}, marketResolved)
}
func (this *Bullish) ParseOrderStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"OPEN":      "open",
		"CLOSED":    "closed",
		"CANCELLED": "canceled",
		"REJECTED":  "rejected",
	}
	return this.SafeString(statuses, status, status)
}
func (this *Bullish) ParseOrderType(typeVar *string) *string {
	var types map[string]any = map[string]any{
		"LMT":        "limit",
		"MKT":        "market",
		"POST_ONLY":  "limit",
		"STOP_LIMIT": "limit",
	}
	return this.SafeString(types, typeVar, typeVar)
}

