func (this *Bullish) LoadAccountAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.loadAccountBody(ch, optionalArgs...)
	return ch
}
func (this *Bullish) loadAccountBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var tradingAccountId any = nil
	var paramsTradingAccountId any = nil
	var tradingAccountIdparamsTradingAccountIdVariable []any = this.HandleOptionStringAndParams(params, "loadAccount", "tradingAccountId")
	tradingAccountId = GetValue(tradingAccountIdparamsTradingAccountIdVariable, 0)
	paramsTradingAccountId = GetValue(tradingAccountIdparamsTradingAccountIdVariable, 1)
	if IsEqual(tradingAccountId, nil) {

		var response []any = ListTyped(PanicOnError((<-this.PrivateGetV1AccountsTradingAccounts(paramsTradingAccountId)).Raw))
		var accounts []any = this.ToArray(response)
		for i := 0; i < len(accounts); i++ {
			var account map[string]any = SafeMapTyped(accounts, i)
			var name *string = this.SafeString(account, "tradingAccountName")
			if name != nil && *name == "Primary Account" {
				tradingAccountId = DerefScalar(this.SafeString(account, "tradingAccountId"))
				break
			}
		}
	}
	if IsEqual(tradingAccountId, nil) {
		panic(ArgumentsRequired(this.Id + " loadAccount() requires a tradingAccountId parameter in options[\"tradingAccountId\"] or params[\"tradingAccountId\"], fetchAccounts() was not able to find the Primary account"))
	}
	this.Options.Store("tradingAccountId", tradingAccountId)

	ch <- tradingAccountId
	return nil
}

