func (this *Bullish) fetchDepositAddressBody(ch chan any, code any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	PanicOnError((<-promiseAll([]any{this.LoadMarketsAsync(), this.HandleTokenAsync()})))
	var currency map[string]any = this.Currency(code)
	var request map[string]any = map[string]any{
		"symbol": currency["id"],
	}

	var response []any = ListTyped(PanicOnError((<-this.PrivateGetV1WalletsDepositInstructionsCryptoSymbol(this.Extend(request, params))).Raw))
	//
	//     [
	//         {
	//             "network": "ETH",
	//             "address": "0xc2fc755082d052bb334763b144851a0031999f33",
	//             "symbol": "ETH"
	//         }
	//     ]
	//
	var safeResponse []any = this.ToArray(response)
	var length int = len(safeResponse)
	var data any = this.SafeDict(safeResponse, 0, map[string]any{})
	var network any = nil
	network = GetValue(this.HandleNetworkCodeAndParams(params), 0)
	var networkDefinedByUser bool = (network != nil)
	if (length > 1) || (networkDefinedByUser) {
		// some currencies have multiple networks
		if network == nil {
			// use default network if not specified and multiple are available
			network = this.DefaultNetworkCode(code)
		}
		if network != nil {
			// find the entry that matches the network or return first entry if not found and user did not specify a network
			for i := 0; i < len(safeResponse); i++ {
				var entry any = this.SafeDict(safeResponse, i, map[string]any{})
				var networkId *string = this.SafeString(entry, "network")
				var networkCode *string = this.NetworkIdToCode(networkId, code)
				if IsEqual(network, networkCode) {
					data = entry
					break
				}
			}
			if networkDefinedByUser {
				data = map[string]any{} // return an empty structure if the user-defined network was not found
			}
		}
	}

	ch <- this.ParseDepositAddress(data, currency)
	return nil
}
func (this *Bullish) ParseDepositAddress(depositAddress any, optionalArgs ...any) any {
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var id *string = this.SafeString(depositAddress, "symbol")
	var network *string = this.SafeString(depositAddress, "network")
	var code *string = this.SafeCurrencyCode(id, currency)
	return map[string]any{
		"info":     depositAddress,
		"currency": code,
		"network":  this.NetworkIdToCode(network, code),
		"address":  this.SafeString(depositAddress, "address"),
		"tag":      nil,
	}
}

/**
 * @method
 * @name bullish#fetchBalance
 * @description query for balance and get the amount of funds available for trading or funds locked in orders
 * @see https://api.exchange.bullish.com/docs/api/rest/trading-api/v2/#get-/v1/accounts/asset
 * @see https://api.exchange.bullish.com/docs/api/rest/trading-api/v2/#get-/v1/accounts/asset/-symbol-
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} params.tradingAccountId the trading account id (mandatory parameter)
 * @param {string} [params.code] unified currency code, default is undefined
 * @returns {object} a [balance structure]{@link https://docs.ccxt.com/?id=balance-structure}
 */
func (this *Bullish) FetchBalanceAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchBalanceBody(ch, optionalArgs...)
	return ch
}
func (this *Bullish) fetchBalanceBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	PanicOnError((<-promiseAll([]any{this.LoadMarketsAsync(), this.HandleTokenAsync()})))

	var tradingAccountId *string = SafeStringPtr(PanicOnError((<-this.LoadAccountAsync(params))))
	var request map[string]any = map[string]any{
		"tradingAccountId": tradingAccountId,
	}
	var response any = nil
	var code *string = this.SafeString(params, "code")
	if code != nil {
		request["symbol"] = this.Currency(code)["id"]

		response = (<-this.PrivateGetV1AccountsAssetSymbol(this.Extend(request, params))).Raw
		PanicOnError(response)

		ch <- this.ParseBalanceForSingleCurrency(response, code)
		return nil
	} else {

		response = (<-this.PrivateGetV1AccountsAsset(this.Extend(request, params))).Raw
		PanicOnError(response)

		//
		//     [
		//         {
		//             "assetId": "10",
		//             "assetSymbol": "AAVE",
		//             "availableQuantity": "10000000.00000000",
		//             "borrowedQuantity": "0.00000000",
		//             "loanedQuantity": "0.00000000",
		//             "lockedQuantity": "0.00000000",
		//             "publishedAtTimestamp": "1747942728870",
		//             "tradingAccountId": "111309424211255",
		//             "updatedAtDatetime": "2025-05-13T11:33:08.801Z",
		//             "updatedAtTimestamp": "1747135988801"
		//         }, ...
		//     ]
		//
		ch <- this.ParseBalance(response)
		return nil
	}
}
func (this *Bullish) ParseBalanceForSingleCurrency(response any, code *string) any {
	var result map[string]any = map[string]any{
		"info": response,
	}
	var account map[string]any = this.Account()
	account["free"] = this.SafeString(response, "availableQuantity")
	account["used"] = this.SafeString(response, "lockedQuantity")
	AddElementToObject(result, code, account)
	return this.SafeBalance(result)
}
func (this *Bullish) ParseBalance(response any) any {
	var result map[string]any = map[string]any{
		"info": response,
	}
	for i := 0; i < GetArrayLength(response); i++ {
		var balance map[string]any = SafeMapTyped(response, i)
		var symbol *string = this.SafeString(balance, "assetSymbol")
		var code *string = this.SafeCurrencyCode(symbol)
		var account map[string]any = this.Account()
		account["total"] = this.SafeString(balance, "availableQuantity")
		account["used"] = this.SafeString(balance, "lockedQuantity")
		if code != nil {
			result[*code] = account
		}
	}
	return this.SafeBalance(result)
}

