/**
 * @method
 * @name bullish#fetchTransfers
 * @description fetch a history of internal transfers made on an account
 * @see https://api.exchange.bullish.com/docs/api/rest/trading-api/v2/#get-/v1/history/transfer
 * @param {string} code unified currency code of the currency transferred
 * @param {int} [since] the earliest time in ms to fetch transfers for
 * @param {int} [limit] the maximum number of transfer structures to retrieve
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {int} params.until the latest time in ms to fetch transfers for (default time now)
 * @param {string} params.tradingAccountId the trading account id
 * @returns {object[]} a list of [transfer structures]{@link https://docs.ccxt.com/?id=transfer-structure}
 */
func (this *Bullish) FetchTransfersAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchTransfersBody(ch, optionalArgs...)
	return ch
}
func (this *Bullish) fetchTransfersBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var code *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = code
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params

	PanicOnError((<-promiseAll([]any{this.LoadMarketsAsync(), this.HandleTokenAsync()})))

	var tradingAccountId *string = SafeStringPtr(PanicOnError((<-this.LoadAccountAsync(params))))
	var maxLimit int = 100
	var paginateparamsPaginateVariable []any = this.HandleOptionBoolAndParams(params, "fetchTransfers", "paginate", false)
	var paginate bool = GetValueBool(paginateparamsPaginateVariable, 0, false)
	var paramsPaginate map[string]any = MapTyped(GetValue(paginateparamsPaginateVariable, 1))
	if paginate {
		var paramsPagination any = this.HandlePaginationParams("fetchTransfers", since, paramsPaginate)

		var retRes265919 []any = ListTyped(PanicOnError((<-this.FetchPaginatedCallDynamicAsync("fetchTransfers", code, since, limit, paramsPagination, maxLimit))))
		ch <- BoxAbsent(retRes265919)
		return nil
	}
	var request map[string]any = map[string]any{
		"tradingAccountId": tradingAccountId,
	}
	var currency map[string]any = nil
	if code != nil {
		currency = this.Currency(code)
		request["assetSymbol"] = GetValue(currency, "id")
	}
	var until *int64 = this.SafeInteger(paramsPaginate, "until")
	// since and until are mandatory for this endpoint, set until to now if both are undefined
	var untilMissing bool = (since == nil) && (until == nil)
	var paramsUntil any = paramsPaginate
	if untilMissing {
		paramsUntil = this.Extend(paramsPaginate, map[string]any{
			"until": this.Milliseconds(),
		})
	}
	var paramsSinceAndUntil any = this.HandleSinceAndUntil(since, paramsUntil)
	if limit != nil {
		request["_pageSize"] = this.GetClosestLimit(limit)
	}

	var response []any = ListTyped(PanicOnError((<-this.PrivateGetV1HistoryTransfer(this.Extend(request, paramsSinceAndUntil))).Raw))

	//
	//     [
	//         {
	//             "requestId": "1",
	//             "toTradingAccountId": "111000000000001",
	//             "fromTradingAccountId": "121000000000001",
	//             "assetSymbol": "BTC",
	//             "quantity": "1.00000000",
	//             "status": "CLOSED",
	//             "statusReasonCode": "6002",
	//             "statusReason": "Executed",
	//             "createdAtTimestamp": "1621490985000",
	//             "createdAtDatetime": "2021-05-20T01:01:01.000Z"
	//         }
	//     ]
	//
	ch <- this.ParseTransfers(response, currency, since, limit)
	return nil
}

