func (this *Bullish) Sign(path string, optionalArgs ...any) any {
	api := GetArg(optionalArgs, 0, "public")
	_ = api
	var method string = GetArgString(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	headers := GetArg(optionalArgs, 3, nil)
	_ = headers
	body := GetArg(optionalArgs, 4, nil)
	_ = body
	var requestHeaders any = headers
	var requestBody any = body
	var request any = this.Omit(params, this.ExtractParams(path))
	var endpoint string = "/" + this.ImplodeParams(path, params)
	var apiUrl *string = this.SafeString(GetValue(this.Urls, "api"), api)
	if apiUrl == nil {
		panic(ExchangeError(this.Id + " sign() has no API URL for this endpoint"))
	}
	var url string = *apiUrl + endpoint
	if IsEqual(api, "private") {
		this.CheckRequiredCredentials()
		var nonce string = strconv.FormatInt(this.Microseconds(), 10)
		var timestamp string = ToString(this.GetTimestamp())
		if method == "GET" {
			var payload string = timestamp + nonce + method + "/trading-api/" + path
			var signature string = this.Hmac(this.Encode(payload), this.Encode(this.Secret), sha256, "hex")
			requestHeaders = map[string]any{
				"BX-TIMESTAMP": timestamp,
				"BX-NONCE":     nonce,
				"BX-SIGNATURE": signature,
			}
		} else if method == "POST" {
			requestBody = this.Json(params)
			var payload *string = SafeStringPtr(Add(timestamp+nonce+method+"/trading-api/"+path, requestBody))
			var digest any = this.Hash(this.Encode(payload), sha256, "hex")
			var signature string = this.Hmac(this.Encode(digest), this.Encode(this.Secret), sha256, "hex")
			requestHeaders = map[string]any{
				"BX-TIMESTAMP": timestamp,
				"BX-NONCE":     nonce,
				"BX-SIGNATURE": signature,
				"Content-Type": "application/json",
			}
			AddElementToObject(requestHeaders, "Content-Type", "application/json")
			var rateLimitToken *string = this.SafeString(request, "rateLimitToken")
			if rateLimitToken != nil {
				AddElementToObject(requestHeaders, "BX-RATE-LIMIT-TOKEN", rateLimitToken)
			}
		}
		if path == "v1/users/hmac/login" {
			requestHeaders = func() any {
				if IsEqual(requestHeaders, nil) {
					return map[string]any{}
				}
				return requestHeaders
			}()
			AddElementToObject(requestHeaders, "BX-PUBLIC-KEY", this.ApiKey)
		} else {
			var token any = this.Token
			if token == nil {
				panic(AuthenticationError(this.Id + " requires a token, please call signIn() first"))
			}
			requestHeaders = func() any {
				if IsEqual(requestHeaders, nil) {
					return map[string]any{}
				}
				return requestHeaders
			}()
			AddElementToObject(requestHeaders, "Authorization", Add("Bearer ", token))
		}
	}
	if method == "GET" {
		var query string = this.Urlencode(request)
		if len(query) > 0 {
			url += "?" + query
		}
	}
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    requestBody,
		"headers": requestHeaders,
	}
}

/**
 * @method
 * @name bullish#signIn
 * @description sign in, must be called prior to using other authenticated methods
 * @see https://api.exchange.bullish.com/docs/api/rest/trading-api/v2/#overview--add-authenticated-request-header
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns response from exchange
 */
func (this *Bullish) SignInAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.signInBody(ch, optionalArgs...)
	return ch
}
func (this *Bullish) signInBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	var response map[string]any = MapTyped(PanicOnError((<-this.PrivateGetV1UsersHmacLogin(params)).Raw))
	//
	//     {
	//         "authorizer": "113363EFA2CA00007368524E02000000",
	//         "ownerAuthorizer": "113363EFA2CA00007368524E02000000",
	//         "token": "eyJhbGciOiJFUzI1NiJ9.eyJpc3MiOiJiMXgtYXV0aC1zZXJ2aWNlIiwic3ViIjoiNDY0OTc4MzAiLCJleHAiOjE3NDczMzgzNDMsIlNUQUdFIjoiQVVUSEVOVElDQVRFRF9XSVRIX0JMT0NLQ0hBSU4ifQ.5FSyrihzc1wsJqAY8pVX36Y4ZXg3HopLJypPEbHg5bBK8FbL_oLxkj6zM_iOYL2a1x6-ICG0pQjr8hF_k8Yg-w"
	//     }
	//
	var token *string = this.SafeString(response, "token")
	var authorizer *string = this.SafeString(response, "authorizer")
	this.Options.Store("authorizer", authorizer)
	this.Token = token
	this.Options.Store("tokenExpires", this.Sum(this.Milliseconds(), (1000*60)*60*24)) // token expires in 24 hours

	ch <- token
	return nil
}
func (this *Bullish) HandleTokenAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.handleTokenBody(ch, optionalArgs...)
	return ch
}
func (this *Bullish) handleTokenBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var now int64 = this.Milliseconds()
	var token any = this.Token
	var tokenExpires *int64 = this.SafeInteger(this.Options, "tokenExpires")
	if (token == nil) || (tokenExpires == nil) || (now > *tokenExpires) {

		ch <- PanicOnError((<-this.SignInAsync()))
		return nil
	} else {

		ch <- this.Token
		return nil
	}
}
func (this *Bullish) HandleErrors(httpCode any, reason any, url any, method any, headers any, body any, response any, requestHeaders any, requestBody any) any {
	if IsEqual(response, nil) {
		return nil // fallback to default error handler
	}
	//
	//         {
	//             "type": "HttpInvalidParameterException",
	//             "message": "HTTP_INVALID_PARAMETER: '100m' is not a valid time bucket"
	//         }
	//
	//         {
	//             "message": "Order size outside valid range",
	//             "raw": null,
	//             "errorCode": 6023,
	//             "errorCodeName": "ORDER_SIZE_OUTSIDE_VALID_RANGE"
	//         }
	//
	var code *string = this.SafeString(response, "errorCode")
	var typeVar *string = this.SafeString(response, "type")
	if ((code != nil) && (code == nil || *code != "0") && (code == nil || *code != "1001")) || (typeVar != nil && *typeVar == "HttpInvalidParameterException") {
		var message any = ""
		var errorCodeName *string = this.SafeString(response, "errorCodeName")
		if errorCodeName != nil {
			message = errorCodeName
		} else {
			message = typeVar
		}
		var feedback *string = SafeStringPtr(Add(this.Id+" ", body))
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], message, feedback)
		this.ThrowBroadlyMatchedException(this.Exceptions["broad"], message, feedback)
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], code, feedback)
		panic(ExchangeError(feedback))
	}
	return nil
}

